var readyPromise = null;
var SCHEMA_VERSION = 2;
async function init() {
  const current = await rawQuery("SELECT value FROM security_config WHERE key = 'schema_version'").catch(() => []);
  if (current[0]?.value === String(SCHEMA_VERSION))
    return;
  const stmts = [
    ...SCHEMA.map((s) => [s]),
    ...SEC_SCHEMA.map((s) => [s])
  ];
  try {
    await batch(stmts);
  } catch {
    await batch(stmts);
  }
  await seedIfEmpty();
  await rawQuery(`INSERT INTO security_config (key, value, updated_by, updated_at) VALUES ('schema_version', $1, 'system', $2)
     ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = EXCLUDED.updated_at`, [String(SCHEMA_VERSION), Date.now()]);
}
function ready() {
  if (!readyPromise) {
    readyPromise = init().catch((e) => {
      readyPromise = null;
      throw e;
    });
  }
  return readyPromise;
}
async function q(text, params = []) {
  await ready();
  return rawQuery(text, params);
}
async function one(text, params = []) {
  const rows = await q(text, params);
  return rows[0] ?? null;
}
async function exec(text, params = []) {
  await q(text, params);
}
