function rateLimit(name, limit, windowMs) {
  return async (c, next) => {
    const ip = (c.req.header("x-forwarded-for") ?? "local").split(",").pop().trim();
    const key = `${name}:${ip}`;
    const now = Date.now();
    const rows = await q(`INSERT INTO rate_limits (key, n, reset_at) VALUES ($1, 1, $2)
       ON CONFLICT (key) DO UPDATE SET
         n = CASE WHEN rate_limits.reset_at < $3 THEN 1 ELSE rate_limits.n + 1 END,
         reset_at = CASE WHEN rate_limits.reset_at < $3 THEN $2 ELSE rate_limits.reset_at END
       RETURNING n, reset_at`, [key, now + windowMs, now]);
    const row = rows[0];
    if (row && row.n > limit) {
      c.header("Retry-After", String(Math.max(1, Math.ceil((row.reset_at - now) / 1000))));
      return c.json({ error: "Too many requests. Please wait a moment." }, 429);
    }
    await next();
  };
}
