var ONCHAIN_CHAINS = FACTS.chains;
var TESTNET_ONCHAIN_CHAINS = FACTS.chains.filter((chain) => chain.isTestnet);
var EVM_PROTOCOL_CONTRACTS = FACTS.protocolContracts;
var BY_CHAIN_ID = new Map(ONCHAIN_CHAINS.map((chain) => [chain.chainId, chain]));
var BY_SCP_BLOCKCHAIN = new Map(ONCHAIN_CHAINS.flatMap((chain) => chain.scpBlockchain ? [[chain.scpBlockchain, chain]] : []));
function getChain(chainId) {
  return BY_CHAIN_ID.get(chainId);
}
function requireChain(chainId) {
  const chain = getChain(chainId);
  if (!chain) {
    throw new Error("Unknown chain ID " + chainId + " — ask Arc Studio to add it to its onchain facts registry");
  }
  return chain;
}
function getUsdc(chainId) {
  return getChain(chainId)?.usdc;
}
function buildTxExplorerUrl(chainId, txHash) {
  return requireChain(chainId).explorerBase + "/tx/" + txHash;
}

