var client2 = apiKey ? import_user_controlled_wallets.initiateUserControlledWalletsClient({ apiKey }) : null;
var circleConfigured = client2 !== null;
function circleError(e) {
  const err = e;
  return {
    code: err.response?.data?.code,
    message: err.response?.data?.message ?? err.message ?? "Circle request failed"
  };
}
var ESCROW_SIGNATURES = new Set([
  "deposit(bytes32,address,uint256)",
  "release(bytes32,address)",
  "dispute(bytes32,address)",
  "refund(bytes32,address)",
  "claim()"
]);
