staffAdmin.post("/requests/:id/approve", requireStaff("staff.manage"), async (c) => {
  const actor = c.get("user").address;
  const req = await one("SELECT * FROM admin_requests WHERE id = $1 AND status = 'pending'", [c.req.param("id")]);
  if (!req)
    return c.json({ error: "Pending request not found." }, 404);
  if (req.requested_by === actor)
    return c.json({ error: "A different admin must approve this." }, 403);
  const claimed = await q("UPDATE admin_requests SET status = 'executed', approved_by = $2, resolved_at = $3 WHERE id = $1 AND status = 'pending' RETURNING id", [req.id, actor, Date.now()]);
  if (claimed.length === 0)
    return c.json({ error: "Already handled." }, 409);
  try {
    const summary = await execute(req.action, JSON.parse(req.payload), req.requested_by);
    await audit({ actor, action: `sensitive.${req.action}`, target: req.id, details: { requestedBy: req.requested_by, summary, mode: "two_person" } });
    return c.json({ ok: true, summary });
  } catch (e) {
    await exec("UPDATE admin_requests SET status = 'rejected' WHERE id = $1", [req.id]);
    return c.json({ error: e instanceof Error ? e.message : "Could not apply the change." }, 400);
  }
});
staffAdmin.post("/requests/:id/reject", requireStaff("staff.manage"), async (c) => {
  const actor = c.get("user").address;
  const gone = await q("UPDATE admin_requests SET status = 'rejected', approved_by = $2, resolved_at = $3 WHERE id = $1 AND status = 'pending' RETURNING id", [c.req.param("id"), actor, Date.now()]);
  if (gone.length === 0)
    return c.json({ error: "Pending request not found." }, 404);
  await audit({ actor, action: "request.reject", target: c.req.param("id") });
  return c.json({ ok: true });
});

