// server/app.ts
var CATEGORIES = new Set(["Electronics", "Fashion", "Art", "Books", "Collectibles", "Home", "Sports", "Other"]);
var DEFAULT_CHAIN = requireChain(DEFAULT_CHAIN_ID);
var api = new Hono3;
api.get("/health", (c) => c.json({ ok: true }));
api.get("/config", (c) => c.json({
  circleConfigured,
  circleAppId: process.env.VITE_CIRCLE_APP_ID ?? null,
  googleClientId: process.env.VITE_GOOGLE_CLIENT_ID ?? null,
  escrowAddress: process.env.VITE_ESCROW_ADDRESS ?? null,
  chainId: DEFAULT_CHAIN_ID
}));
var fxCache = null;
api.get("/fx", async (c) => {
  const now = Date.now();
  if (fxCache && now - fxCache.updatedAt < 60 * 60 * 1000)
    return c.json({ base: "USD", ...fxCache });
  try {
    const res = await fetch("https://open.er-api.com/v6/latest/USD", { signal: AbortSignal.timeout(6000) });
    if (!res.ok)
      throw new Error(`FX upstream ${res.status}`);
    const json2 = await res.json();
    if (json2.result !== "success" || !json2.rates)
      throw new Error("FX upstream error");
    fxCache = { rates: json2.rates, updatedAt: now };
    return c.json({ base: "USD", ...fxCache });
  } catch {
    if (fxCache)
      return c.json({ base: "USD", ...fxCache, stale: true });
    return c.json({ error: "Exchange rates are unavailable right now." }, 503);
  }
});
var signInMessage = (nonce) => `Sign in to TradePort
Nonce: ${nonce}`;
api.post("/auth/nonce", rateLimit("nonce", 20, 60000), async (c) => {
  const body = await c.req.json().catch(() => ({}));
  const address = addr(body.address);
  if (!address)
    return c.json({ error: "Valid address required." }, 400);
  const nonce = randomBytes4(16).toString("hex");
  await exec(`INSERT INTO nonces (address, nonce, expires_at) VALUES ($1, $2, $3)
     ON CONFLICT (address) DO UPDATE SET nonce = EXCLUDED.nonce, expires_at = EXCLUDED.expires_at`, [address, nonce, Date.now() + 5 * 60000]);
  return c.json({ message: signInMessage(nonce) });
});
api.post("/auth/verify", rateLimit("verify", 20, 60000), async (c) => {
  const body = await c.req.json().catch(() => ({}));
  const address = addr(body.address);
  const signature = str(body.signature, 400);
  if (!address || !signature)
    return c.json({ error: "address and signature required." }, 400);
  const meta = clientMeta(c, body.deviceId);
  const failures = await one("SELECT COUNT(*)::int AS n FROM security_events WHERE address = $1 AND kind = 'login_failed' AND at > $2", [address, Date.now() - 15 * 60000]);
  if ((failures?.n ?? 0) >= 8) {
    return c.json({ error: "Too many failed attempts. Please wait 15 minutes and try again." }, 429);
  }
  const row = await one("SELECT nonce, expires_at FROM nonces WHERE address = $1", [address]);
  if (!row || row.expires_at < Date.now()) {
    await recordEvent({ address, kind: "login_failed", severity: "warn", ipHash: meta.ipHash, details: { reason: "expired" } });
    return c.json({ error: "Sign-in expired. Try again." }, 401);
  }
  const ok = await verifyMessage3({
    address,
    message: signInMessage(row.nonce),
    signature
  }).catch(() => false);
  if (!ok) {
    await recordEvent({ address, kind: "login_failed", severity: "warn", ipHash: meta.ipHash, details: { reason: "bad_signature" } });
    return c.json({ error: "Signature did not match this wallet." }, 401);
  }
  await exec("DELETE FROM nonces WHERE address = $1", [address]);
  const user = await upsertUser({ address, method: "wallet" });
  const { token } = await createSession(address, meta);
  return c.json({ token, user: publicUser(user) });
});
api.post("/auth/logout", async (c) => {
  const t = bearerToken(c);
  if (t)
    await destroySession(t);
  return c.json({ ok: true });
});
