var REPORT_KINDS = new Set(["counterfeit", "not_as_described", "scam", "prohibited", "other"]);
api.post("/listings/:id/report", requireAuth, rateLimit("report", 10, 3600000), async (c) => {
  const user = c.get("user");
  const body = await c.req.json().catch(() => ({}));
  const kind = typeof body.kind === "string" && REPORT_KINDS.has(body.kind) ? body.kind : null;
  if (!kind)
    return c.json({ error: "Choose what is wrong with this listing." }, 400);
  const l = await one("SELECT * FROM listings WHERE id = $1 AND status IN ('active','review')", [c.req.param("id")]);
  if (!l)
    return c.json({ error: "Listing not found." }, 404);
  if (l.seller === user.address)
    return c.json({ error: "You cannot report your own listing." }, 400);
  const rows = await q(`INSERT INTO reports (id, listing_id, reporter, kind, details, created_at) VALUES ($1, $2, $3, $4, $5, $6)
     ON CONFLICT (listing_id, reporter, kind) DO NOTHING RETURNING id`, [randomUUID5(), l.id, user.address, kind, optStr(body.details, 1000), Date.now()]);
  if (rows.length === 0)
    return c.json({ ok: true, duplicate: true });
  const distinct = await one("SELECT COUNT(DISTINCT reporter)::int AS n FROM reports WHERE listing_id = $1", [l.id]);
  let caseId = (await one("SELECT id FROM cases WHERE kind = 'listing_report' AND subject = $1 AND status <> 'closed' LIMIT 1", [l.seller]))?.id;
  if (!caseId)
    caseId = await openCase({ kind: "listing_report", severity: "medium", subject: l.seller, title: `Reports on listing: ${l.title.slice(0, 80)}`, by: "system" });
  await exec("UPDATE reports SET case_id = $2 WHERE id = $1", [rows[0].id, caseId]);
  if ((distinct?.n ?? 0) >= 3 && l.status === "active") {
    await exec("UPDATE listings SET status = 'review' WHERE id = $1 AND status = 'active'", [l.id]);
    await audit({ actor: "system", action: "listing.auto_hold", target: l.id, details: { reporters: distinct?.n } });
  }
  return c.json({ ok: true }, 201);
});
api.get("/orders/mine", requireAuth, async (c) => {
  const user = c.get("user");
  const rows = await q(`SELECT o.*, l.title FROM orders o JOIN listings l ON l.id = o.listing_id
     WHERE o.buyer = $1 OR o.seller = $1 ORDER BY o.created_at DESC LIMIT 200`, [user.address]);
  return c.json({
    orders: rows.map((o) => ({
      id: o.id,
      listingId: o.listing_id,
      title: o.title,
      role: o.buyer === user.address ? "buyer" : "seller",
      amountUsdc: o.amount_usdc,
      displayCurrency: o.display_currency,
      displayAmount: o.display_amount,
      txHash: o.tx_hash,
      status: o.status,
      verifiedNote: o.verify_note,
      createdAt: new Date(Number(o.created_at)).toISOString()
    }))
  });
});
api.route("/wallet", wallet);
api.route("/payments", payments);
api.route("/security", security);
api.route("/staff", staff);
var app = new Hono3;
app.use("*", async (c, next) => {
  await next();
  c.header("X-Content-Type-Options", "nosniff");
  c.header("Referrer-Policy", "no-referrer");
  c.header("Permissions-Policy", "camera=(self), microphone=(), geolocation=(self), payment=()");
  c.header("Strict-Transport-Security", "max-age=15552000");
  c.header("Content-Security-Policy", "object-src 'none'; base-uri 'self'; form-action 'self'");
  if (c.req.path.startsWith("/api/"))
    c.header("Cache-Control", "no-store");
});
app.onError((err, c) => {
  console.error("request failed:", c.req.method, c.req.path, err instanceof Error ? err.message : "unknown error");
  return c.json({ error: "Something went wrong. Please try again." }, 500);
});
app.notFound((c) => c.json({ error: "Not found" }, 404));
app.route("/api", api);
app.all("/api/*", (c) => c.json({ error: "Not found" }, 404));

// server/vercel-entry.ts
var vercel_entry_default = getRequestListener(app.fetch);
export {
  vercel_entry_default as default
};
